import IFile from "../storage/IFile";
import Log from "../core/Log";
import { EventDispatcher, IEventHandler } from "ste-events";
import StorageUtilities from "../storage/StorageUtilities";
import { ITerrainTextureCatalog, ITerrainTextureDataItem } from "./ITerrainTextureCatalog";
import Project, { FolderContext } from "../app/Project";
import ProjectItem from "../app/ProjectItem";
import { ProjectItemType } from "../app/IProjectItemData";
import Utilities from "../core/Utilities";
import Database from "./Database";
import IDefinition from "./IDefinition";

export default class TerrainTextureCatalogDefinition implements IDefinition {
  private _data?: ITerrainTextureCatalog;
  private _file?: IFile;
  private _isLoaded: boolean = false;
  private _loadedWithComments: boolean = false;

  public id: string | undefined;

  private _onLoaded = new EventDispatcher<TerrainTextureCatalogDefinition, TerrainTextureCatalogDefinition>();

  public get isLoaded() {
    return this._isLoaded;
  }

  public get data() {
    return this._data;
  }

  public get file() {
    return this._file;
  }

  public get onLoaded() {
    return this._onLoaded.asEvent();
  }

  public set file(newFile: IFile | undefined) {
    this._file = newFile;
  }

  public get textureData() {
    if (!this._data) {
      return undefined;
    }

    if (this._data.texture_data === undefined) {
      this._data.texture_data = {};
    }

    return this._data.texture_data;
  }

  public getTexturePathList() {
    if (!this._data || !this._data.texture_data) {
      return undefined;
    }

    const textureList = [];

    for (const key in this._data.texture_data) {
      const texturePathArr = this._data.texture_data[key];

      if (texturePathArr && texturePathArr.textures) {
        if (typeof texturePathArr.textures === "string") {
          textureList.push(texturePathArr.textures.toLowerCase());
        } else if (Array.isArray(texturePathArr.textures)) {
          for (const texturePath of texturePathArr.textures) {
            if (typeof texturePath === "string") {
              textureList.push(texturePath.toLowerCase());
            } else if (texturePath.path) {
              textureList.push(texturePath.path.toLowerCase());
            } else if (typeof texturePath === "object" && (texturePath as any).variations) {
              for (const variation of (texturePath as any).variations) {
                if (typeof variation === "string") {
                  textureList.push(variation.toLowerCase());
                } else if (variation.path && typeof variation.path === "string") {
                  textureList.push(variation.path.toLowerCase());
                }
              }
            }
          }
        }
      }
    }

    return textureList;
  }

  public get texturesIdList() {
    if (!this._data || !this._data.texture_data) {
      return undefined;
    }

    const textureIdList = [];

    for (const key in this._data.texture_data) {
      textureIdList.push(key);
    }

    return textureIdList;
  }

  getTerrainTextureDefinition(id: string) {
    if (!this._data || !this._data.texture_data) {
      return undefined;
    }

    return this._data.texture_data[id];
  }

  static async getTerrainTextureCatalog(project: Project) {
    const terrainTextureItems = project.getItemsByType(ProjectItemType.terrainTextureCatalogResourceJson);

    if (terrainTextureItems && terrainTextureItems.length > 0) {
      if (!terrainTextureItems[0].isContentLoaded) {
        await terrainTextureItems[0].loadContent();
      }

      if (terrainTextureItems[0].primaryFile) {
        return await TerrainTextureCatalogDefinition.ensureOnFile(terrainTextureItems[0].primaryFile);
      }
    }

    return undefined;
  }

  static async ensureTerrainTextureCatalog(project: Project) {
    let terrainTextureCatalog = await this.getTerrainTextureCatalog(project);

    if (terrainTextureCatalog) {
      return terrainTextureCatalog;
    }

    const defaultRp = await project.getDefaultResourcePackFolder();

    if (defaultRp) {
      const terrainTextureCatalogFile = await defaultRp.ensureFileFromRelativePath("/textures/terrain_texture.json");

      terrainTextureCatalogFile.setContent(
        JSON.stringify({
          texture_name: "atlas.terrain",
          padding: 8,
          num_mip_levels: 4,
          texture_data: {},
        })
      );

      project.ensureItemFromFile(
        terrainTextureCatalogFile,
        ProjectItemType.terrainTextureCatalogResourceJson,
        FolderContext.resourcePack
      );

      return await TerrainTextureCatalogDefinition.ensureOnFile(terrainTextureCatalogFile);
    }

    return undefined;
  }

  static async ensureOnFile(
    file: IFile,
    loadHandler?: IEventHandler<TerrainTextureCatalogDefinition, TerrainTextureCatalogDefinition>
  ) {
    let et: TerrainTextureCatalogDefinition | undefined;

    if (file.manager === undefined) {
      et = new TerrainTextureCatalogDefinition();

      et.file = file;

      file.manager = et;
    }

    if (file.manager !== undefined && file.manager instanceof TerrainTextureCatalogDefinition) {
      et = file.manager as TerrainTextureCatalogDefinition;

      if (!et.isLoaded) {
        if (loadHandler) {
          et.onLoaded.subscribe(loadHandler);
        }

        await et.load();
      }
    }

    return et;
  }

  getAllTexturePaths(textureId: string) {
    if (!this.data || !this.data.texture_data) {
      return undefined;
    }

    const elt = this.data.texture_data[textureId];

    if (!elt) {
      return undefined;
    }

    if (typeof elt.textures === "string") {
      return [elt.textures];
    } else if (Array.isArray(elt.textures) && elt.textures.length > 0) {
      const texturePaths: string[] = [];

      for (const tex of elt.textures) {
        if (typeof tex === "string") {
          texturePaths.push(tex);
        } else if (tex.path) {
          texturePaths.push(tex.path);
        }
      }

      return texturePaths;
    }

    return undefined;
  }

  getTexture(textureId: string) {
    if (!this.data || !this.data.texture_data) {
      return undefined;
    }

    return this.data.texture_data[textureId];
  }

  setTexture(textureId: string, textureData: ITerrainTextureDataItem) {
    if (!this.data || !this.data.texture_data) {
      return;
    }

    this.data.texture_data[textureId] = textureData;

    this.persist();
  }

  getDefaultTexturePath(textureId: string) {
    if (!this.data || !this.data.texture_data) {
      return undefined;
    }

    const elt = this.data.texture_data[textureId];

    if (!elt) {
      return undefined;
    }

    if (typeof elt.textures === "string") {
      return elt.textures;
    } else if (Array.isArray(elt.textures) && elt.textures.length > 0) {
      if (typeof elt.textures[0] === "string") {
        return elt.textures[0];
      } else if (elt.textures[0].path) {
        return elt.textures[0].path;
      }
    }

    return undefined;
  }

  persist(): boolean {
    if (this._file === undefined) {
      return false;
    }

    if (!this._data) {
      Log.unexpectedUndefined("TTCDF");
      return false;
    }

    return this._file.setObjectContentIfSemanticallyDifferent(this._data);
  }

  getTextureReferences() {
    const textureRefs: string[] = [];
    if (this.data?.texture_data) {
      for (const resourceId in this.data.texture_data) {
        const resource = this.data.texture_data[resourceId];

        if (resource && resource.textures) {
          if (!textureRefs.includes(resourceId)) {
            textureRefs.push(resourceId);
          }
        }
      }
    }

    return textureRefs;
  }

  getPackRootFolder() {
    let packRootFolder = undefined;
    if (this.file && this.file.parentFolder) {
      let parentFolder = this.file.parentFolder;

      packRootFolder = StorageUtilities.getParentOfParentFolderNamed("textures", parentFolder);
    }

    return packRootFolder;
  }

  async addChildItems(project: Project, item: ProjectItem) {
    const itemsCopy = project.getItemsCopy();

    let packRootFolder = this.getPackRootFolder();

    let texturePathList = this.getTexturePathList();

    for (const candItem of itemsCopy) {
      if (candItem.itemType === ProjectItemType.texture && packRootFolder && texturePathList) {
        if (!candItem.isContentLoaded) {
          await candItem.loadContent();
        }

        if (candItem.primaryFile) {
          let relativePath = StorageUtilities.getBaseRelativePath(candItem.primaryFile, packRootFolder);

          if (relativePath) {
            // texturePathList is lowercased, so we need to compare case-insensitively
            const relativePathLower = relativePath.toLowerCase();
            if (texturePathList && texturePathList.includes(relativePathLower)) {
              item.addChildItem(candItem);

              texturePathList = Utilities.removeItemInArray(relativePathLower, texturePathList);
            }
          }
        }
      }
    }

    if (texturePathList) {
      for (const texturePath of texturePathList) {
        item.addUnfulfilledRelationship(
          texturePath,
          ProjectItemType.texture,
          await Database.isVanillaToken(texturePath)
        );
      }
    }
  }

  /**
   * Loads the definition from the file.
   * @param preserveComments If true, uses comment-preserving JSON parsing for edit/save cycles.
   *                         If false (default), uses efficient standard JSON parsing.
   *                         Can be called again with true to "upgrade" a read-only load to read/write.
   */
  async load(preserveComments: boolean = false) {
    // If already loaded with comments, we have the "best" version - nothing more to do
    if (this._isLoaded && this._loadedWithComments) {
      return;
    }

    // If already loaded without comments and caller doesn't need comments, we're done
    if (this._isLoaded && !preserveComments) {
      return;
    }

    if (this._file === undefined) {
      Log.unexpectedUndefined("TTCDF");
      return;
    }

    if (!this._file.isContentLoaded) {
      await this._file.loadContent();
    }

    if (!this._file.content || this._file.content instanceof Uint8Array) {
      this._isLoaded = true;
      this._loadedWithComments = preserveComments;
      this._onLoaded.dispatch(this, this);
      return;
    }

    let data: any = {};

    // Use comment-preserving parser only when needed for editing
    let result = preserveComments
      ? StorageUtilities.getJsonObjectWithComments(this._file)
      : StorageUtilities.getJsonObject(this._file);

    if (result) {
      data = result;
    }

    this._data = data;

    this._isLoaded = true;
    this._loadedWithComments = preserveComments;

    this._onLoaded.dispatch(this, this);
  }
}
